const addr=x=>{if(typeof x!=='string'||!/^0x[0-9a-f]{40}$/i.test(x)||BigInt(x)===0n)throw Error('Địa chỉ không hợp lệ.');return x.toLowerCase();};
const word=x=>{x=BigInt(x);if(x<0n||x>=2n**256n)throw Error('Số lượng không hợp lệ.');return x.toString(16).padStart(64,'0');};
const aw=x=>addr(x).slice(2).padStart(64,'0');
const returned=x=>{if(!/^0x0{24}[a-f0-9]{40}$/i.test(x))throw Error('Dữ liệu địa chỉ không hợp lệ.');return addr('0x'+x.slice(-40));};
const call=(to,data,block='latest')=>['eth_call',[{to,data},block]];
const quoteData=(amount,path)=>'0xd06ca61f'+word(amount)+word(64)+word(2)+path.map(aw).join('');
const quoteOut=(x,n)=>{if(!/^0x[a-f0-9]{256}$/i.test(x)||BigInt('0x'+x.slice(2,66))!==32n||BigInt('0x'+x.slice(66,130))!==2n||BigInt('0x'+x.slice(130,194))!==n)throw Error('Giá đổi không hợp lệ.');const out=BigInt('0x'+x.slice(194));if(out<=0n)throw Error('Pool không có thanh khoản.');return out;};
const format=(n,d=18,places=8)=>{n=BigInt(n);const base=10n**BigInt(d);let frac=(n%base).toString().padStart(d,'0').slice(0,places).replace(/0+$/,'');return (n/base).toString()+(frac?'.'+frac:'');};
const allowed=new Set(['eth_chainId','eth_blockNumber','eth_getBlockByNumber','eth_getCode','eth_call','eth_estimateGas','eth_gasPrice','eth_getBalance','eth_getTransactionReceipt','eth_getTransactionByHash']);
async function batch(items,fetcher=fetch){
 if(items.some(([m])=>!allowed.has(m)))throw Error('Phương thức đọc không được phép.');
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);
 try{const r=await fetcher(C.rpc,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(items.map(([method,params],id)=>({jsonrpc:'2.0',id,method,params}))),signal:controller.signal});if(!r.ok)throw Error('Mạng Testnet chưa phản hồi.');const data=await r.json();if(!Array.isArray(data)||data.length!==items.length)throw Error('Dữ liệu mạng chưa đầy đủ.');const values=new Map();for(const x of data){if(!Number.isInteger(x.id)||x.id<0||x.id>=items.length||values.has(x.id)||x.error||!Object.hasOwn(x,'result'))throw Error('Không đọc được dữ liệu Testnet.');values.set(x.id,x.result);}return items.map((_,i)=>values.get(i));}finally{clearTimeout(timer);}
}
async function hashCode(code){if(!/^0x(?:[a-f0-9]{2})+$/i.test(code))throw Error('Hợp đồng không tồn tại.');const bytes=Uint8Array.from(code.slice(2).match(/../g),x=>parseInt(x,16));return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');}
async function snapshot(read=batch){
 const [chain,block]=await read([['eth_chainId',[]],['eth_blockNumber',[]]]);if(BigInt(chain)!==97n)throw Error('Sai mạng. Chỉ hỗ trợ Testnet 97.');
 const items=[['eth_getBlockByNumber',[block,false]],...Object.keys(pins).map(a=>['eth_getCode',[a,block]]),call(C.router,'0xc45a0155',block),call(C.factory,'0xe6a43905'+aw(C.cash)+aw(C.asset),block),call(C.pair,'0x0dfe1681',block),call(C.pair,'0xd21220a7',block),call(C.pair,'0x0902f1ac',block),call(C.cash,'0x313ce567',block),call(C.asset,'0x313ce567',block),call(C.cash,'0x70a08231'+aw(C.wallet),block),call(C.asset,'0x70a08231'+aw(C.wallet),block),call(C.cash,'0xdd62ed3e'+aw(C.wallet)+aw(C.router),block),call(C.asset,'0xdd62ed3e'+aw(C.wallet)+aw(C.router),block),['eth_getBalance',[C.wallet,block]]];
 const v=await read(items),now=Math.floor(Date.now()/1000),head=v[0];if(!head||now-Number(BigInt(head.timestamp))>60||now<Number(BigInt(head.timestamp)))throw Error('Dữ liệu mạng đã cũ. Bấm cập nhật lại.');
 for(let i=0;i<3;i++)if(await hashCode(v[1+i])!==Object.values(pins)[i])throw Error('Hợp đồng đã thay đổi; dừng giao dịch.');
 if(returned(v[4])!==C.factory||returned(v[5])!==C.pair||returned(v[6])!==C.asset||returned(v[7])!==C.cash)throw Error('Pool hoặc token không đúng.');
 if(!/^0x[a-f0-9]{192}$/i.test(v[8]))throw Error('Dự trữ pool không hợp lệ.');const ar=BigInt('0x'+v[8].slice(2,66)),sr=BigInt('0x'+v[8].slice(66,130)),stamp=BigInt('0x'+v[8].slice(130));if(ar<=0n||sr<=0n||ar>=2n**112n||sr>=2n**112n||stamp>=2n**32n)throw Error('Pool không hợp lệ.');
 if(BigInt(v[9])!==18n||BigInt(v[10])!==18n)throw Error('Độ chính xác token đã thay đổi.');
 const cash=BigInt(v[11]),asset=BigInt(v[12]),value=asset*sr/ar,total=cash+value,weight=total?Number(value*10000n/total):0;
 return {now,block,blockHash:head.hash,cash,asset,value,total,weight,ar,sr,cashAllowance:BigInt(v[13]),assetAllowance:BigInt(v[14]),native:BigInt(v[15])};
}
function decision(s){if(!s.total)return {kind:'HOLD',reason:'Ví chưa có token thử nghiệm.'};if(Math.abs(s.weight-C.target)<C.drift)return {kind:'HOLD',reason:'Tỷ trọng đang trong vùng mục tiêu.'};const delta=s.total*BigInt(C.target)/10000n-s.value,buy=delta>0n,notional=(buy?delta:-delta)<C.cap?(buy?delta:-delta):C.cap,amount=buy?(notional<s.cash?notional:s.cash):((notional*s.ar/s.sr)<s.asset?notional*s.ar/s.sr:s.asset);if(amount<=0n)return {kind:'HOLD',reason:'Không đủ token cho điều chỉnh này.'};return {kind:'CANDIDATE',buy,amount,input:buy?C.cash:C.asset,path:buy?[C.cash,C.asset]:[C.asset,C.cash],allowance:buy?s.cashAllowance:s.assetAllowance};}

