let memo=null,inflight=null;
async function live(){if(memo&&Date.now()-memo.at<30000)return memo.data;if(!inflight)inflight=(async()=>{const s=await snapshot(),d=decision(s);const data={observedAt:new Date(s.now*1000).toISOString(),chainId:97,wallet:C.wallet,block:s.block,blockHash:s.blockHash,balances:{U:format(s.cash,18,18),WBNB:format(s.asset,18,18),tBNB:format(s.native,18,18)},allocation:{WBNBPercent:s.weight/100,targetPercent:30,driftPercentagePoints:5,valuation:'test pool reserve ratio; not a USD market price'},decision:d.kind,reason:d.kind==='HOLD'?d.reason:'Portfolio outside the drift band; owner review required.',candidate:d.kind==='CANDIDATE'?{side:d.buy?'buy':'sell',inputToken:d.buy?'U':'WBNB',amount:format(d.amount,18,18),executed:false}:null,identity,automaticExecution:false,campaignQualification:'unconfirmed',cacheMaxSeconds:30};memo={at:Date.now(),data};return data;})().finally(()=>inflight=null);return inflight;}
function err(id,code,message){return json({jsonrpc:'2.0',id,error:{code,message}});}
async function rpc(request){let b;try{const declared=Number(request.headers.get('content-length')||0);if(declared>8192)return json({error:'Request too large'},413);const text=await request.text();if(new TextEncoder().encode(text).length>8192)return json({error:'Request too large'},413);b=JSON.parse(text);}catch{return err(null,-32700,'Invalid JSON');}if(!b||Array.isArray(b)||b.jsonrpc!=='2.0'||!Object.hasOwn(b,'id')||!['string','number'].includes(typeof b.id))return err(null,-32600,'Single JSON-RPC request with id required');if(b.method!=='message/send')return err(b.id,-32601,'Only message/send is supported');const m=b.params?.message;if(!m||m.role!=='user'||typeof m.messageId!=='string'||!m.messageId||!Array.isArray(m.parts)||m.parts.length!==1||m.parts[0].kind!=='text'||typeof m.parts[0].text!=='string')return err(b.id,-32602,'Send one user text part with messageId');if(m.taskId||m.contextId)return err(b.id,-32602,'Stateless agent: task/context continuation unsupported');const q=m.parts[0].text.trim().toLowerCase();let data;if(['status','decision','số dư','trạng thái'].includes(q)){try{data=await live();}catch{return err(b.id,-32000,'Testnet read unavailable; no decision issued. Retry later.');}}else if(q==='evidence')data=evidence;else return err(b.id,-32602,'Supported commands: status, decision, evidence. Trading is unavailable.');return json({jsonrpc:'2.0',id:b.id,result:{kind:'message',role:'agent',messageId:crypto.randomUUID(),parts:[{kind:'text',text:q==='evidence'?'Verified historical owner-signed testnet execution evidence.':data.decision+': '+data.reason},{kind:'data',data}],metadata:{readOnly:true,protocolVersion:'0.3.0'}}});}
async function auditedRpc(request){
 const response=await rpc(request);
 const body=await response.clone().json();
 const data=body.result?.parts?.find(p=>p.kind==='data')?.data;
 const audit={event:'a2a_response',version:card.version,probeId:crypto.randomUUID(),httpStatus:response.status,rpcSuccess:body.jsonrpc==='2.0'&&body.result?.role==='agent'&&!body.error,errorCode:body.error?.code??null,readOnly:body.result?.metadata?.readOnly===true,chainId:data?.chainId??null,observedAt:data?.observedAt??null,decision:data?.decision??null,block:data?.block??null};
 console.info(JSON.stringify(audit));
 return response;
}
