const html=`<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fual Treasury Agent</title><style>body{background:#0b1511;color:#eef2ec;font:17px/1.65 system-ui;margin:0}main{max-width:880px;margin:auto;padding:42px 24px}header{color:#dcc17b;letter-spacing:4px}h1{font-size:clamp(34px,7vw,64px);line-height:1.12}h2{font-size:25px}section{border:1px solid #37443b;padding:24px;border-radius:22px;margin:24px 0}button{background:#e0c27e;color:#172219;border:0;border-radius:12px;padding:16px;font:inherit;font-weight:700;cursor:pointer;width:100%}a{color:#e0c27e}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.6 monospace}.muted{color:#b3c0b5}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}@media(max-width:600px){.grid{grid-template-columns:1fr}}footer{font-size:14px;color:#b3c0b5}</style><main><header>FUAL · TREASURY AGENT</header><h1>Đọc danh mục.<br>Giải thích quyết định.</h1><p class="muted">Agent cân bằng danh mục thử nghiệm BNB: mục tiêu 30% WBNB, 70% U. Chỉ đề xuất điều chỉnh khi lệch ít nhất 5 điểm phần trăm. Mỗi giao dịch cần chủ ví duyệt riêng.</p><section><h2>Hỏi agent ngay</h2><p>Đọc số dư thật trên BNB Testnet và nhận quyết định hiện tại. Không cần kết nối ví.</p><button id="check">Kiểm tra danh mục thử nghiệm</button><button id="a2acheck" style="margin-top:12px">Kiểm tra A2A công khai</button><p id="a2astatus" role="status"></p><pre id="a2aresult"></pre><p id="status" role="status">Chưa gọi dữ liệu mới.</p><pre id="result"></pre></section><div class="grid"><section><h2>Danh tính</h2><p>ERC-8004 · ID 370316<br>BNB Smart Chain · 56</p><p class="muted">URI trong registry đã được đọc và xác nhận trỏ tới website này ngày 15/10/2026. Lệnh thử nghiệm chạy trên chain 97; việc quy thuộc các lệnh cho ID này chưa được xác nhận.</p><a href="https://www.agent.family/agents/cmv272a0kg4y8zw01sg7tclan">Hồ sơ marketplace</a></section><section><h2>Bằng chứng đã thực hiện</h2><p>Ngày 13/10/2026: ba lần đổi U sang WBNB, trong đó hai lần qua trang điều khiển. Sau lần cuối: 30,20% WBNB và GIỮ NGUYÊN.</p><a href="/evidence">Xem dữ liệu bằng chứng</a></section></div><section><h2>Cân bằng Testnet trên ví của bạn</h2><p>Bản thử nghiệm miễn phí: bạn giữ tài sản, duyệt từng giao dịch và xuất hồ sơ. Chưa tạo đơn thuê hoặc chạy tự động.</p><a href="/rebalance/">Mở bản thử nghiệm cho khách</a></section><section><h2>Dành cho ứng dụng gọi agent</h2><p><a href="/.well-known/agent-card.json">Agent card</a> · <a href="/health">Health</a> · <a href="/api/decision">Quyết định JSON</a></p><p>A2A 0.3.0 · JSON-RPC message/send tại /a2a. Hỗ trợ: status, decision, evidence. Không hỗ trợ giao dịch, streaming hay lưu hội thoại.</p><a href="https://github.com/superfual/bnb-rotation-treasury-agent/tree/feat/testnet-owner-rebalance">Mã nguồn dự án</a></section><footer>Chỉ dùng token thử nghiệm. Đây là bộ quyết định theo quy tắc, không phải dịch vụ giao dịch tự động hoặc bằng chứng đã đủ điều kiện Set & Earn. Fual Nguyễn.</footer></main><script>document.getElementById('check').onclick=async()=>{const b=document.getElementById('check'),s=document.getElementById('status'),r=document.getElementById('result');b.disabled=true;r.textContent='';s.textContent='Đang đọc BNB Testnet…';try{const response=await fetch('/api/decision');const d=await response.json();if(!response.ok)throw Error(d.error||'Không đọc được dữ liệu mới');s.textContent=(d.decision==='HOLD'?'GIỮ NGUYÊN':'CẦN CHỦ VÍ XEM XÉT')+' · WBNB '+d.allocation.WBNBPercent+'%';r.textContent='U: '+d.balances.U+'\\nWBNB: '+d.balances.WBNB+'\\ntBNB cho phí: '+d.balances.tBNB+'\\nDữ liệu: '+d.observedAt+'\\nKhông có giao dịch được gửi.';}catch(e){s.textContent=e.message+' — chưa có quyết định mới.';}finally{b.disabled=false;}};document.getElementById('a2acheck').onclick=async()=>{const b=document.getElementById('a2acheck'),s=document.getElementById('a2astatus'),r=document.getElementById('a2aresult');b.disabled=true;r.textContent='';s.textContent='Đang gửi yêu cầu A2A qua website công khai…';const id=crypto.randomUUID();try{const response=await fetch('/a2a',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id,method:'message/send',params:{message:{role:'user',messageId:crypto.randomUUID(),parts:[{kind:'text',text:'status'}]}}})});if(!response.ok)throw Error('HTTP '+response.status);const d=await response.json();if(d.error)throw Error(d.error.message);if(d.id!==id||d.result?.role!=='agent')throw Error('Phản hồi A2A không hợp lệ');const data=d.result.parts.find(p=>p.kind==='data')?.data;if(!data||data.chainId!==97||!data.observedAt)throw Error('Thiếu dữ liệu Testnet');s.textContent='A2A THÀNH CÔNG · '+(data.decision==='HOLD'?'GIỮ NGUYÊN':data.decision)+' · WBNB '+data.allocation.WBNBPercent+'%';r.textContent=JSON.stringify({checkedAt:new Date().toISOString(),method:'message/send',httpStatus:response.status,requestId:id,replyId:d.id,data},null,2);}catch(e){s.textContent='A2A chưa xác nhận: '+e.message;}finally{b.disabled=false;}};</script></html>`;
